list_discount_profiles.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.discountProfiles().listDiscountProfiles(Map.of("sort", "name", "dir", "asc"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("discount_profiles")) {
    Map<?, ?> profile = (Map<?, ?>) row;
    System.out.println(profile.get("id") + " " + profile.get("name") + " " + profile.get("type"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

get_discount_profile.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.discountProfiles().getDiscountProfile(1001);
Map<?, ?> profile = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("discount_profile");
System.out.println(profile.get("name") + " " + profile.get("is_active") + " " + profile.get("default_coupon_code"));
for (Object row : (List<?>) profile.get("customer_coupons")) {
    Map<?, ?> coupon = (Map<?, ?>) row;
    System.out.println(coupon.get("code") + " " + coupon.get("customer_email"));
}

update_discount_profile.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;
import static java.util.Map.entry;

ApiResponse response = client.discountProfiles().updateDiscountProfile(1001, Map.ofEntries(
        entry("name", "Spring 50 Off"), entry("type", "offer_coupon"), entry("discount_details_type", "amount"),
        entry("amount_details", Map.of("type", "single", "apply_to", "total_order", "single_amount", 50,
                "single_amount_type", "PERCENT", "minimum_amount_on", "each_item")),
        entry("is_active", true), entry("start_date", "2026-11-06 09:30:00"), entry("is_specify_end_date", true),
        entry("end_date", "2026-11-20 18:00:00"), entry("is_apply_coupon_code", true),
        entry("is_maximum_use_total", true), entry("maximum_use_count", 150), entry("is_maximum_use_customer", true),
        entry("maximum_use_customer_count", 1), entry("is_maximum_discount_allowed", true),
        entry("maximum_discount_allowed_amount", 200), entry("is_display_text_coupon", true),
        entry("is_display_text_cart", true)));
Map<?, ?> profile = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("discount_profile");
System.out.println(profile.get("name") + " " + profile.get("end_date") + " " + profile.get("maximum_use_count"));

